CREATE TABLE `approvals` (`id` text PRIMARY KEY NOT NULL, `workspace_id` text NOT NULL, `case_id` text NOT NULL, `recommendation_id` text, `status` text NOT NULL, `approved_by` text NOT NULL, `approval_notes` text, `decided_at` integer, `created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL, `updated_at` integer DEFAULT (unixepoch() * 1000) NOT NULL, FOREIGN KEY (`workspace_id`) REFERENCES `workspaces`(`id`), FOREIGN KEY (`case_id`) REFERENCES `cases`(`id`), FOREIGN KEY (`approved_by`) REFERENCES `users`(`id`));
CREATE INDEX `approvals_workspace_case_id_idx` ON `approvals` (`workspace_id`,`case_id`);